// ── EA-PS2342 Live Readout ────────────────────────────────────────────────────
// To stop: click "Scripts" in the left nav (if not already there),
// then close this toast to reveal the Stop button underneath.
const INTERVAL_MS = 100;

await connection.acquire(true);
var liveToast = notify.info("\u25b6 Live: connecting...", { autoClose: false });

try {
    while (!session.isStopped) {
        var both = qts(await connection.query("MEAS:BOTH?")).split("|");
        var a1 = both.length >= 1 ? both[0].split(",") : [];
        var a2 = both.length >= 2 ? both[1].split(",") : [];

        function fmtCh(a, n) {
            if (a.length < 4) return "CH"+n+": \u2013\u2013\u2013";
            var trk = (a.length > 4 && a[4]==="1") ? " \u21d4TRK" : "";
            return "CH"+n+": "
                + parseFloat(a[0]).toFixed(3)+"V  "
                + parseFloat(a[1]).toFixed(4)+"A  "
                + (a[2]==="1" ? "\u25cf\u202fON " : "\u25cb\u202fOFF")
                + " "+a[3]+trk;
        }

        notify.update(liveToast, {
            render: fmtCh(a1,1)+"\n"+fmtCh(a2,2),
            autoClose: false
        });
        await new Promise(r=>setTimeout(r,INTERVAL_MS));
    }
    notify.update(liveToast, { render: "Live stopped", autoClose: 2000 });
} catch(e) {
    notify.update(liveToast, { render: "Live failed: "+e.message, autoClose: 5000, type: "error" });
} finally {
    connection.release();
}

