// ── EA-PS2342 Output Control ──────────────────────────────────────────────────
await resetAndAcquire();
try {
    var tracking = false;
    try { tracking = qts(await connection.query("TRACK?")) === "1"; } catch(te) {}

    var vals = await input({
        title: "EA-PS2342  —  Output Control"
            + (tracking ? "  [TRACKING ON]" : ""),
        size: "small",
        fields: [
            { name:"ch1", displayName:"CH1 Output", type:"enum",
              enumItems:[{id:"ON",label:"On"},{id:"OFF",label:"Off"},
                         {id:"-",label:"(no change)"}] },
            { name:"ch2", displayName:"CH2 Output", type:"enum",
              enumItems: tracking
                ? [{id:"-",label:"Follows CH1 (tracking on)"}]
                : [{id:"ON",label:"On"},{id:"OFF",label:"Off"},
                   {id:"-",label:"(no change)"}] }
        ]
    }, { ch1:"ON", ch2: tracking ? "-" : "ON" });

    if (!vals) { notify.info("Cancelled"); connection.release(); return; }

    if (vals.ch1 !== "-" && !tracking && vals.ch2 !== "-") {
        await connection.query("OUTP:BOTH "+vals.ch1+","+vals.ch2);
    } else {
        if (vals.ch1 !== "-") connection.command("OUTP 1,"+vals.ch1);
        if (!tracking && vals.ch2 !== "-") connection.command("OUTP 2,"+vals.ch2);
    }

    await new Promise(r=>setTimeout(r,300));
    var both = qts(await connection.query("MEAS:BOTH?")).split("|");
    var s1 = both.length >= 1 ? both[0].split(",") : [];
    var s2 = both.length >= 2 ? both[1].split(",") : [];
    var trkMsg = tracking ? "  [tracking]" : "";
    notify.info(
        "CH1: "+(s1[2]==="1"?"ON":"OFF")+" "+s1[3]
        +"\nCH2: "+(s2[2]==="1"?"ON":"OFF")+" "+s2[3]+trkMsg
    );
} catch(e) { notify.error("Output control failed: "+e.message); }
finally { connection.release(); }

