    var a1 = both.length >= 1 ? both[0].split(",") : [];
    var a2 = both.length >= 2 ? both[1].split(",") : [];
    var trk = (a1.length > 4 && a1[4]==="1") ? "  [TRACKING ON]" : "";
    notify.info("CH1: "+(a1[2]==="1"?"ON":"OFF")+"\nCH2: "+(a2[2]==="1"?"ON":"OFF")+trk);
} catch(e) { notify.error("Both Off failed: "+e.message); }
finally { connection.release(); }

function qts(r){
    if(r===null||r===undefined)return"";
    if(typeof r==="string")return r.trim();
    if(typeof r==="number")return String(r);
    if(r.data){var t=new TextDecoder().decode(new Uint8Array(r.data));return t.trim();}
    return String(r).trim();
}
async function resetAndAcquire(){
    try{connection.release();}catch(e){}
    await new Promise(r=>setTimeout(r,400));
    await connection.acquire(true);
}

// ── EA-PS2342 Diagnostic ──────────────────────────────────────────────────────
await resetAndAcquire();
try {
    notify.info("EA-PS2342 Diag: querying...");
    var idn = qts(await connection.query("*IDN?"));
    notify.info("IDN: "+idn);
    var info = JSON.parse(qts(await connection.query("INFO?")));
    notify.info("Type: "+info.type
        +"  Nom: "+info.nom_voltage+"V / "+info.nom_current+"A"
        +"  fw "+info.version);

    // SETP:BOTH? and MEAS:BOTH? — two round-trips instead of four
    var setp = qts(await connection.query("SETP:BOTH?")).split("|");
    var s1 = setp.length >= 1 ? setp[0].split(",") : [];
    var s2 = setp.length >= 2 ? setp[1].split(",") : [];
    var trk = s1.length >= 4 ? s1[3]==="1" : false;
    notify.info("Tracking: "+(trk ? "ON (CH2 mirrors CH1)" : "OFF"));

    var meas = qts(await connection.query("MEAS:BOTH?")).split("|");
    var a1 = meas.length >= 1 ? meas[0].split(",") : [];
    var a2 = meas.length >= 2 ? meas[1].split(",") : [];

    for (var ch = 1; ch <= 2; ch++) {
        var a = ch===1 ? a1 : a2;
        var s = ch===1 ? s1 : s2;
        var trkA = (a.length > 4 && a[4]==="1") ? " TRK" : "";
        notify.info("CH"+ch
            +"  actual: "+parseFloat(a[0]||0).toFixed(3)+"V  "
            +parseFloat(a[1]||0).toFixed(4)+"A  "
            +(a[2]==="1"?"ON":"OFF")+" "+(a[3]||"??")+trkA
            +"  |  set: "+parseFloat(s[0]||0).toFixed(3)+"V / "
            +parseFloat(s[1]||0).toFixed(4)+"A");
    }
} catch(e) { notify.error("Diag failed: "+e.message); }
finally { connection.release(); notify.info("Diag done."); }
